mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
tok = None
log = []
def get_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""), timeout=30)
            tok = json.load(r)["token"]; return
        except urllib.error.HTTPError as e:
            log.append(("token", e.code, dict(e.headers)))
            wait(e)
def wait(e):
    ra = e.headers.get("Retry-After")
    body = e.read().decode(errors="replace")
    log.append(("body", e.code, body))
    try: s = float(ra)
    except (TypeError, ValueError): s = 1.0
    time.sleep(s + 0.1)
def get(path):
    if tok is None: get_token()
    for attempt in range(200):
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            return 200, json.loads(r.read())
        except urllib.error.HTTPError as e:
            log.append((path, e.code, e.headers.get("Retry-After")))
            if e.code == 401 or e.code == 403:
                e.read(); get_token(); continue
            if e.code == 404: return 404, json.loads(e.read() or b"{}")
            wait(e)
        except Exception as ex:
            log.append((path, "exc", repr(ex))); time.sleep(1)
    raise RuntimeError("gave up " + path)
pages = {}
path = "/orders?page=1"
while path:
    code, d = get(path)
    pages[d["page"]] = d
    print(path, d["page"], d["total_pages"], len(d["items"]), d["next"], file=sys.stderr)
    path = d["next"]
json.dump(pages, open("/tmp/recon/pages.json", "w"))
cids = sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
custs = {}
for c in cids:
    code, d = get("/customers/" + c)
    custs[c] = {"code": code, "data": d}
json.dump(custs, open("/tmp/recon/customers.json", "w"))
json.dump(log, open("/tmp/recon/log.json", "w"), default=str)
print("done", len(pages), len(cids), file=sys.stderr)
EOF
cd /tmp/recon && timeout 590 python3 -I fetch.py 2>&1 | tail -40

